def count_common(words):
    # Count occurrences of each word using defaultdict from collections
    word_count = {}
    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1

    # Find the maximum occurrence count
    max_occurrences = max(word_count.values())

    # Filter and return words with the maximum occurrence
    common_words = [(word, count) for word, count in word_count.items() if count == max_occurrences]

    return common_words

