def binomial_Coeff(n,k):
    # Calculate the factorial of n and k using recursion
    def fact(x):
        if x == 0 or x == 1:
            return 1
        else:
            return x * fact(x-1)

    # Apply the formula for binomial coefficient: C(n, k) = (n! / (k! * (n-k)!))
    return fact(n) // (fact(k) * fact(n-k))

# Test the function with the provided example
assert binomial_Coeff(5,2) == 10

