import heapq

def func(arr):
    # Initialize a dictionary to keep track of integer counts
    count = {}

    # Iterate over each sublist and update the count
    for sublist in arr:
        for num in sublist:
            if num not in count:
                count[num] = 0
            count[num] += 1

    # Create a max-heap based on the counts
    heap = []
    for key, value in count.items():
        heapq.heappush(heap, (-value, key))

    # Extract the top k elements
    result = []
    while heap and len(result) < k:
        _, num = heapq.heappop(heap)
        result.append(num)

    return result[::-1]  # Return the result in reverse order to match the expected output format

