def max_Prime_Factors(n):
    # Initialize the maximum prime factor to 1
    max_prime = 1

    # Divide n by 2 until it's odd
    while n % 2 == 0:
        max_prime = 2
        n //= 2

    # Check for odd factors
    i = 3
    while i * i <= n:
        if n % i == 0:
            max_prime = i
            n //= i
        else:
            i += 2

    # If n is a prime number greater than 2
    if n > 2:
        max_prime = n

    return max_prime

