def find_missing(nums):
    left = 0
    right = len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        # If the middle element is not equal to its index
        if nums[mid] != mid + 1:
            return mid + 1  # Return the missing number
        else:
            # If the next element is also not equal to its index, then the missing number is in the range [mid+1, right]
            if mid + 1 < len(nums) and nums[mid + 1] != mid + 2:
                return mid + 2
            else:
                # Otherwise, the missing number is in the range [left, mid-1]
                right = mid - 1

    # If no missing number is found, return None or raise an error depending on requirements
    return None

