def find_Sum(arr, n):
    """
    Find the sum of repeated elements in an array.

    Parameters:
    arr (list): The input list of integers.
    n (int): The length of the input list.

    Returns:
    int: The sum of all repeated elements in the array.
    """
    # Create a dictionary to store the frequency of each element
    freq_map = {}
    for i in range(n):
        if arr[i] in freq_map:
            freq_map[arr[i]] += 1
        else:
            freq_map[arr[i]] = 1

    # Calculate the sum of all repeated elements
    total_sum = 0
    for key, value in freq_map.items():
        if value > 1:
            total_sum += key * value

    return total_sum

