def compute_Last_Digit(a, b):
    """
    Computes the last digit of (a! / b!) for given integers a and b.

    Parameters:
    a (int): The numerator in the fraction a! / b!
    b (int): The denominator in the fraction a! / b!

    Returns:
    int: The last digit of the result of (a! / b!).
    """
    # Reduce b to its prime factors
    prime_factors = {}
    for i in range(2, b + 1):
        while b % i == 0:
            if i in prime_factors:
                prime_factors[i] += 1
            else:
                prime_factors[i] = 1
            b //= i

    # Compute the product of all prime factors with even exponents
    exponent_product = 1
    for factor, exponent in prime_factors.items():
        if exponent % 2 == 0:
            exponent_product *= factor ** (exponent // 2)

    # Find the last digit of the factorial of the reduced factor
    last_digit_factorial = 1
    for i in range(1, exponent_product + 1):
        last_digit_factorial

