def factorial(n):
    """Compute the factorial of n."""
    if n == 0 or n == 1:
        return 1
    else:
        result = 1
        for i in range(2, n + 1):
            result *= i
        return result

def bell_number(n):
    """Compute the nth Bell number using dynamic programming."""
    # Initialize the first few Bell numbers
    bell = [0] * (n + 1)
    bell[0] = 1

    # Compute Bell numbers iteratively
    for i in range(1, n + 1):
        for j in range(i):
            bell[i] += bell[j] * factorial(i - j - 1)

    return bell[n]

# Example usage:
print(bell_number(5))  # Output: 52

