def extract_missing(ranges, start_range, end_range):
    # Initialize the result list with all possible ranges from start_range to end_range
    result = list(range(start_range, end_range + 1))

    # Iterate through each range in the input list
    for rng in ranges:
        # Extract the start and end points of the current range
        start, end = rng

        # Remove the overlapping or completely contained parts of the current range from the result list
        for i in range(len(result) - 1, -1, -1):
            if result[i] >= end:
                del result[i]
            elif result[i] <= start:
                result[i:i+2] = []

    return result

