def multiply_int(x, y):
    # Base case: if one of the numbers is 0, the product is 0
    if x == 0 or y == 0:
        return 0

    # Recursive case: add x to the result of multiplying x and (y-1)
    elif y > 0:
        return x + multiply_int(x, y - 1)

    # If y is negative, convert it to positive and use the recursive case
    else:
        return -multiply_int(x, -y)

