def max_occurrences(arr):
    # Use dictionary to store elements and their frequencies
    freq_map = {}

    # Iterate through each element in the array
    for num in arr:
        if num in freq_map:
            # If the element is already in the dictionary, increment its count
            freq_map[num] += 1
        else:
            # If the element is not in the dictionary, add it with a count of 1
            freq_map[num] = 1

    # Find the element with the maximum frequency
    max_freq_element = max(freq_map, key=freq_map.get)
    max_freq_count = freq_map[max_freq_element]

    return (max_freq_element, max_freq_count)

