def reverse_vowels(s):
    # Filter out vowels and store them in a list
    vowels = [char for char in s if char.lower() in 'aeiou']

    # Reverse the vowel list
    vowels.reverse()

    # Initialize an empty string to build the result
    result = []

    # Iterate through each character in the original string
    for char in s:
        # If the character is a vowel, replace it with the next vowel from the reversed list
        if char.lower() in 'aeiou':
            result.append(vowels.pop(0))
        else:
            result.append(char)

    # Join the characters in the result list to form the final string
    return ''.join(result)

