def cal_electbill(units):
    # Calculate electricity cost based on the units used.
    if units <= 100:
        return units * 0.50  # First 100 units at $0.50 per unit
    elif units <= 300:
        return 100 * 0.50 + (units - 100) * 0.75  # Next 200 units at $0.75 per unit
    else:
        return 100 * 0.50 + 200 * 0.75 + (units - 300) * 1.00  # After 300 units at $1.00 per unit

