def is_Sum_Of_Powers_Of_Two(num):
    # Check if num is zero, return False immediately if true
    if num == 0:
        return False

    # Iterate from 2 (the smallest power of two greater than 0)
    while num > 1:
        # If num is even, divide it by 2 and continue
        if num % 2 == 0:
            num //= 2
        else:
            # If num is odd, it cannot be expressed as a sum of powers of two
            return False

    # If num becomes 1, it was representable as a sum of powers of two
    return True

# Example usage
print(is_Sum_Of_Powers_Of_Two(10))  # Output: True

