def is_Sum_Of_Powers_Of_Two(num):
    # Check if the number is zero
    if num == 0:
        return False

    # Iterate through all powers of 2 less than or equal to num
    while num > 0:
        # If num is not a power of 2, it cannot be represented as sum of non-zero powers of 2
        if num & (num - 1):
            return False
        num >>= 1

    return True

