# Helper function to get the smallest non-null neighbor of a cell (i,j)
def get_neighbor(i, j, row):
    left = row[i][j-1] if j > 0 else None
    right = row[i][j+1] if j < len(row[i]) - 1 else None
    return min(left, right)

# Main function to compute the maximum path sum
def max_path_sum(triangle, i, j):
    # Base case: the topmost row is already considered with its only element
    if i == len(triangle) - 1:
        return triangle[i][j]

    # Recursively calculate the maximum path sum for the current cell
    curr_val = triangle[i][j] + get_neighbor(i, j, triangle)
    return curr_val + max(max_path_sum(triangle, i+1, j), max_path_sum(triangle, i+1, j+1))

