    for i in range(1, n1+1):
        for j in range(1, n2+1):
            if seq1[i-1] == seq2[j-1]:
                dp[i][j] = 1 + dp[i-1][j-1]
            else:
                dp[i][j] = max(dp[i][j-1], dp[i-1][j])

    # The length of LCS is stored in dp[n1][n2]
    return dp[n1][n2]

