def longest_common_subsequence(seq1, seq2, n1, n2):
    # Initialize a 2D array 'dp' where dp[i][j] represents the length of LCS of seq1[0:i] and seq2[0:j]
    dp = [[0]*(n2+1) for _ in range(n1+1)]

    # Fill the dp table
    for i in range(1, n1+1):
        for j in range(1, n2+1):
            if seq1[i-1] == seq2[j-1]:
                dp[i][j] = 1 + dp[i-1][j-1]
            else:
                dp[i][j] = max(dp[i][j-1], dp[i-1][j])

    # The length of LCS is stored in dp[n1][n2]
    return dp[n1][n2]

# Example usage
print(longest_common_subsequence("AGGTAB" , "GXTXAYB", 6, 7))  # Output: 4

