def prod_Square(n):
    # Check if a number is perfect square
    def is_perfect_square(x):
        s = int(x**0.5)
        return s*s == x

    # Iterate through all possible factors of n
    for i in range(1, int(n**0.5)+1):
        if n % i == 0 and is_perfect_square(i):
            j = n // i
            if is_perfect_square(j):
                return True
    return False

