    # First, move all negative numbers to the end of the array
    nums.append(0)
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = 0

    # Use index as hash key and sign of the number at that index as flag
    for i in range(n):
        index = abs(nums[i]) - 1
        nums[index] = -abs(nums[index])

    # Find the first positive index + 1 which represents the smallest missing positive number
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    # If no missing positive number is found (all are present), return n+1
    return n + 1

