def count_Intgral_Points(x_min, y_min, x_max, y_max):
    count = 0
    for i in range(x_min, x_max + 1):
        for j in range(y_min, y_max + 1):
            if all((i % 2 != 0, j % 2 != 0)):
                count += 1
    return count

