def first(arr, target, start, end):
    if start > end:
        return -1  # Not found

    mid = start + (end - start) // 2

    if arr[mid] == target:
        if mid == 0 or arr[mid-1] < target:
            return mid
        else:
            return first(arr, target, start, mid-1)

    elif arr[mid] < target:
        return first(arr, target, mid+1, end)

    else:
        return first(arr, target, start, mid-1)

