def replace_max_specialchar(string, n):
    special_chars = {' ': 1, ',': 1, '.': 1}
    count_dict = {}

    # Count occurrences of each special character
    for char in string:
        if char in special_chars:
            if char in count_dict:
                count_dict[char] += 1
            else:
                count_dict[char] = 1

    # Sort characters based on their occurrence and limit to n
    sorted_chars = sorted(count_dict.items(), key=lambda item: -item[1])[:n]

    # Replace special characters with ':'
    result_string = ''.join([char if char not in [special_char for _, special_char in sorted_chars] else ':' for char in string])

    return result_string

