    start = -1
    end = -1
    left = 0
    right = n-1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == x and (start == -1 or mid < start):
            start = mid

        if arr[mid] >= x:
            right = mid - 1
        else:
            left = mid + 1

    if start != -1:
        return start < n//2
    else:
        return False

