        if arr[mid] == x:
            first_occurrence = mid
            end = mid - 1
        elif arr[mid] < x:
            start = mid + 1
        else:
            end = mid - 1

    # Calculate the index of the last occurrence of x
    last_occurrence = first_occurrence
    while last_occurrence < size - 1 and arr[last_occurrence + 1] == x:
        last_occurrence += 1

    # Check if the count of x from first occurrence to last occurrence is greater than half of size
    return (last_occurrence - first_occurrence + 1) > size // 2

