def max_sum(triangle, rows):
    # Start from the second last row and move upwards
    for i in range(rows-2, -1, -1):
        for j in range(len(triangle[i])):
            # Update the value at current position with the sum of itself and the maximum of its two children
            triangle[i][j] += max(triangle[i+1][j], triangle[i+1][j+1])

    # The top element now contains the maximum sum
    return triangle[0][0]

# Example usage:
print(max_sum([[1], [2,1], [3,3,2]], 3))  # Output: 6

