def get_total_number_of_sequences(n, m):
    if n <= 0 or m < 1:
        return 0

    # Initialize a list to store the number of valid sequences ending with each value from 0 to m
    dp = [0] * (m + 1)

    # There's one way to have a sequence of length 1 (the number itself)
    dp[1] = 1

    # Fill the dp array
    for i in range(2, n + 1):
        for j in range(i):
            # The current sequence can end with any number from (j * 2) + 1 to min(j * 2 + i, m)
            dp[i] += max(0, m - (j * 2 + i))

    # The total number of valid sequences of length n is the sum of all values in the dp array
    return sum(dp)

# Test the function
print(get_total_number_of_sequences(10, 4))  # Expected output: 4

