def sort_on_occurence(tuples_list):
    # Create a dictionary to count occurrences of the first element of each tuple
    occurrences = {}
    for item in tuples_list:
        if item[0] in occurrences:
            occurrences[item[0]].append(item)
        else:
            occurrences[item[0]] = [item]

    # Sort the items based on their count and then by their first element
    sorted_items = sorted(occurrences.values(), key=lambda x: (-len(x), x[0]))

    # Flatten the list of lists into a single list
    result = []
    for sublist in sorted_items:
        result.extend(sublist)

    return result

