def max_sum(arr):
    n = len(arr)

    # Initialize the DP table
    dp = [[0] * n for _ in range(n)]

    # Fill the DP table
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] < arr[j]:
                dp[i][j] = max(dp[i][j-1], arr[i] + dp[i+1][j])
            else:
                dp[i][j] = dp[i+1][j]

    # Find the maximum sum of bi-tonic sub-sequence
    max_sum = 0
    for i in range(n):
        for j in range(n):
            if dp[i][j] > max_sum:
                max_sum = dp[i][j]

    return max_sum

# Test the function with the provided example
print(max_sum([1, 15, 51, 45, 33, 100, 12, 18, 9], 9))  # Output: 194

