def lps(s):
    n = len(s)

    # Create a table to store lengths of longest palindromic subseqences
    L = [[0 for x in range(n)] for y in range(n)]

    # Fill L[][] in bottom up manner
    for i in range(n):
        L[i][i] = 1

    for length in range(2, n+1):
        for start in range(n-length+1):
            end = start + length - 1
            if s[start] == s[end] and length == 2:
                L[start][end] = 2
            elif s[start] == s[end]:
                L[start][end] = L[start+1][end-1] + 2
            else:
                L[start][end] = max(L[start][end-1], L[start+1][end])

    return L[0][n-1]

