def get_Position(arr,n,x):
    # Find the first occurrence of x in the array
    first_index = -1
    for i in range(n):
        if arr[i] == x:
            first_index = i
            break

    # If x is not found in the array, return -1
    if first_index == -1:
        return -1

    # Find the last occurrence of x in the array
    last_index = -1
    for i in range(n-1, first_index-1, -1):
        if arr[i] == x:
            last_index = i
            break

    return last_index

