def flatten_list(nested_list):
    """
    Flatten a given nested list structure.

    Args:
    nested_list (list): A list which may contain integers or other lists.

    Returns:
    list: A flattened version of the input nested list.
    """
    def helper(sub_list):
        for item in sub_list:
            if isinstance(item, list):
                yield from helper(item)
            else:
                yield item

