def count_unset_bits(n):
    # Initialize the count of unset bits to zero
    unset_bits_count = 0
    while n > 0:
        # If the least significant bit is not set, increment the count
        if (n & 1) == 0:
            unset_bits_count += 1
        # Right shift the number by one position
        n >>= 1
    return unset_bits_count

