def permute_string(s):
    if len(s) == 1:
        return [s]

    # Recursive call on the rest of the string
    perms = permute_string(s[1:])

    # Insert the current character at every possible position in each permutation
    result = []
    for perm in perms:
        for i in range(len(perm) + 1):
            result.append(perm[:i] + s[0] + perm[i:])

    return result

