    counts = {}

    # Count occurrences of each element in the tuple
    for element in tup:
        if element in counts:
            counts[element] += 1
        else:
            counts[element] = 1

    # Replace duplicate elements with 'MSP'
    result = []
    for element in tup:
        if counts[element] > 1:
            result.append('MSP')
        else:
            result.append(element)

    return tuple(result)

