def find_rotation_count(arr):
    n = len(arr)
    low, high = 0, n - 1

    while low <= high:
        if arr[low] <= arr[high]:
            return low

        mid = (low + high) // 2

        # Check if mid is the pivot point
        if arr[mid] > arr[mid + 1]:
            return mid + 1

        # If left part is not sorted, move to right
        if arr[low] <= arr[mid]:
            low = mid + 1
        else:
            high = mid - 1

    return 0  # Should never reach here

# Example usage:
print(find_rotation_count([8, 9, 10, 1, 2, 3, 4, 5, 6, 7]))  # Output: 3

