    # Iterate through each character in the string
    for char in bracket_string:
        if char == '[' or char == '{':
            # Push opening brackets onto the stack
            stack.append(char)
        elif char == ']' or char == '}':
            # Check if there is a corresponding opening bracket at the top of the stack
            if not stack or (char == ']' and stack[-1] != '[') or (char == '}' and stack[-1] != '{'):
                return -1  # No matching opening bracket found
            # Pop the matching opening bracket from the stack
            stack.pop()

    # If all brackets are balanced, return the number of swaps needed
    if len(stack) == 0:
        return 0
    else:
        # If there are unmatched opening brackets left, calculate the number of swaps needed
        swaps_needed = len(stack) * 2
