def extract_freq(lst):
    # Initialize an empty dictionary to store the frequency of tuples
    freq_dict = {}

    # Iterate over each tuple in the list
    for tup in lst:
        # If the tuple is already in the dictionary, increment its count
        if tup in freq_dict:
            freq_dict[tup] += 1
        # Otherwise, add the tuple to the dictionary with a count of 1
        else:
            freq_dict[tup] = 1

    # Return the number of unique tuples and their frequencies
    return len(freq_dict), {tup: freq for tup, freq in freq_dict.items()}

