def count_bidirectional(tuples_list):
    # Create a dictionary to store the occurrences of each element
    element_count = {}

    # Count the occurrences of each element in both directions
    for tup in tuples_list:
        if tup[0] in element_count:
            element_count[tup[0]] += 1
        else:
            element_count[tup[0]] = 1

        if tup[1] in element_count:
            element_count[tup[1]] += 1
        else:
            element_count[tup[1]] = 1

    # Calculate the number of bidirectional pairs by summing up all occurrences
    # of elements with even counts
    bidirectional_pairs = sum(1 for count in element_count.values() if count % 2 == 0)

    return str(bidirectional_pairs)

