    pair_counts = {}

    # Iterate through the list of tuples
    for tup in tuples_list:
        # Add the pair to the dictionary or increment its count if already present
        if tup[0] < tup[1]:
            key = (tup[0], tup[1])
        else:
            key = (tup[1], tup[0])

        if key in pair_counts:
            pair_counts[key] += 1
        else:
            pair_counts[key] = 1

    # Count the total number of bidirectional pairs
    total_pairs = sum(pair_counts.values())

    return str(total_pairs)

