    unique_tuples = set(tuples_list)

    # Initialize counter for bidirectional pairs
    bidirectional_pairs_count = 0

    # Iterate through each pair of tuples in the set
    for i in range(len(unique_tuples)):
        for j in range(i + 1, len(unique_tuples)):
            # Check if both pairs are in the original list or reversed versions
            if (unique_tuples[i], unique_tuples[j]) in tuples_list or (unique_tuples[j], unique_tuples[i]) in tuples_list:
                bidirectional_pairs_count += 1

    return str(bidirectional_pairs_count)

