    # Initialize an empty dictionary to store occurrences
    occurrence_dict = {}

    # Iterate over each element in the input list 'a_list'
    for element in a_list:
        # If the element is already in the dictionary, increment its count
        if element in occurrence_dict:
            occurrence_dict[element] += 1
        # Otherwise, add the element with a count of 1
        else:
            occurrence_dict[element] = 1

    # Return the dictionary containing the counts of each element in 'b_list'
    return {element: occurrence_dict.get(element, 0) for element in b_list}

