def Find_Min(lst):
    # Initialize the minimum length with the first list's length
    min_length = len(lst[0])

    # Iterate through each sublist in the list of lists
    for sublist in lst:
        # Update the minimum length if the current sublist is shorter
        if len(sublist) < min_length:
            min_length = len(sublist)

    return min_length

