def drop_empty(dictionary):
    """
    This function takes a dictionary as input and returns a new dictionary
    with all the key-value pairs where the value is not None.

    Args:
    dictionary (dict): The input dictionary from which empty values need to be removed.

    Returns:
    dict: A new dictionary with only non-empty key-value pairs.
    """
    return {key: value for key, value in dictionary.items() if value is not None}

# Check function to verify the correctness of the solution
def check_function():
    assert drop_empty({'c1': 'Red', 'c2': 'Green', 'c3':None}) == {'c1': 'Red', 'c2': 'Green'}
    assert drop_empty({'a': 0, 'b': '', 'c': 5, 'd': None, 'e': True}) == {'a': 0, 'b': '', 'c': 5, 'e': True}
    assert drop_empty({}) == {}
    print("All checks passed!")

# Run the check function to validate the solution
check_function()

