def find_peak(arr, size):
    if size == 1:
        return arr[0]

    left = 0
    right = size - 1

    while left < right:
        mid = (left + right) // 2

        if arr[mid] > arr[mid + 1]:
            right = mid
        else:
            left = mid + 1

    return arr[left]

# Test the function with the provided example
