def find_peak(arr, n):
    if n <= 1:
        return arr[0]

    low = 0
    high = n - 1

    while low < high:
        mid = (low + high) // 2

        # Check if the middle element is greater than its neighbors
        if arr[mid] > arr[mid + 1]:
            high = mid
        else:
            low = mid + 1

    # At the end of the loop, low/high will point to the peak element
    return arr[high]

