def max_profit(prices, k):
    n = len(prices)
    if n <= 1 or k <= 0:
        return 0

    # Initialize variables to store the maximum profit at each step and transaction count
    dp = [[0] * (k + 1) for _ in range(n)]

    for i in range(1, n):
        for j in range(1, k + 1):
            dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - 1] + prices[i] - prices[i - 1])

    return dp[n - 1][k]

