def is_subset_sum(nums, n, total):
    # Create a 2D array to store results of subproblems
    dp = [[False for _ in range(total + 1)] for _ in range(n + 1)]

    # Initialize the first column (0 sum) as true because there's always an empty subset that sums up to 0
    for i in range(n + 1):
        dp[i][0] = True

    # Fill the table in bottom-up manner
    for i in range(1, n + 1):
        for j in range(1, total + 1):
            if nums[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - nums[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][total]

# Example usage
print(is_subset_sum([3, 34, 4, 12, 5, 2], 6, 9))  # Output: True

