def largest_palindrome(arr):
    # Convert all elements in the array to strings for easy comparison
    arr_str = [str(i) for i in arr]

    # Find the maximum length of the numbers in the array
    max_len = len(str(max(arr)))

    # Iterate through the range of possible lengths (from max_len down to 1)
    for length in range(max_len, 0, -1):
        # Iterate through all possible substrings of the current length
        for start_index in range(len(arr)):
            substring = arr_str[start_index:start_index + length]

            # Reverse the substring and compare with the original substring
            if substring == substring[::-1]:
                # If it's a palindrome, convert back to integer and return it
                return int(''.join(substring))

    # Return None if no palindrome is found
    return None

