def gcd(a, b):
    # Ensure that a is always greater than or equal to b
    if a < b:
        a, b = b, a

    # Base case: if b is zero, then a is the GCD
    if b == 0:
        return a

    # Recursive case: apply the Euclidean algorithm
    else:
        return gcd(b, a % b)

